  function statusClass(st){return st==='approved'?'#047857':st==='rejected'?'#b91c1c':st==='returned_for_revision'?'#b45309':'#0369a1'}
  function decorateArchive(){if(!isPrivate())return;var all=[];keys().forEach(function(k){arr(k).forEach(function(r){if(r&&r.workflowReportKey)all.push(r)})});if(!all.length)return;var nodes=[].slice.call(document.querySelectorAll('.archive-item-card,[class*=archive-item],#archive-content>div>div,#archive-content .bg-white'));
    nodes.forEach(function(n){var text=(n.textContent||'').trim(),r=all.find(function(x){return titleOf(x)&&text.indexOf(titleOf(x))>-1});if(!r)return;var st=r.approvalStatus||'',tag=n.querySelector('[data-ss-approval-badge]');if(!tag){tag=document.createElement('div');tag.setAttribute('data-ss-approval-badge','1');tag.style.cssText='margin-top:8px;font-size:11px;font-weight:900';var first=n.firstElementChild||n;first.appendChild(tag)}tag.innerHTML='<span style="display:inline-block;padding:5px 9px;border-radius:999px;background:'+statusClass(st)+'15;color:'+statusClass(st)+';border:1px solid '+statusClass(st)+'35">'+esc(LABELS[st]||st)+'</span>'+(r.managerDecisionReason?'<div style="margin-top:6px;color:#b45309">سبب المدير: '+esc(r.managerDecisionReason)+'</div>':'');var btns=[].slice.call(n.querySelectorAll('button'));btns.forEach(function(b){var bt=(b.textContent||'').trim();if(st==='approved'){if(/حذف|تعديل|فتح/.test(bt))b.style.display='none'}else if(st==='returned_for_revision'){if(/فتح/.test(bt))b.textContent='تعديل';if(/تعديل|فتح/.test(bt))b.style.display='';if(/حذف/.test(bt))b.style.display='none'}else if(st==='rejected'){if(/حذف/.test(bt))b.style.display='';if(/تعديل|فتح/.test(bt))b.style.display='none'}})})}
