  window.ssPerformanceDecision=async function(id,decision){if(!bridge())return;var note='';if(decision==='return'||decision==='reject'){note=prompt(decision==='return'?'اكتب سبب إعادة التقرير للتعديل:':'اكتب سبب عدم اعتماد التقرير:')||'';if(!note.trim()){alert('يجب كتابة السبب قبل تنفيذ القرار.');return}}try{await bridge().performance('decision',{approvalId:id,decision:decision,note:note});await openManagerQueue();await refreshQueueCount();if(typeof window.showToast==='function')window.showToast(decision==='approve'?'تم اعتماد التقرير بنجاح ✅':decision==='return'?'تمت إعادة التقرير للتعديل.':'تم تسجيل التقرير كغير معتمد.')}catch(e){alert(e.message||String(e))}}
